// testdata/edge.json is KeyClerk tests/conformance/edge.json at the tag in testdata/SOURCE, unchanged;
// testdata/canon.json is generated by testdata/gen_canon.py from keyclerk.edge.canonical.
// Both come from the reference, so they can falsify this port.

type conformance struct {
	Format   string `json:"format"`
	Verifier struct {
		Cases []struct {
			Name     string         `json:"name"`
			Now      string         `json:"now"`
			Pins     Pins           `json:"pins"`
			Sealed   jsontext.Value `json:"sealed"`
			State    State          `json:"state"`
			Expected struct {
				OK            bool           `json:"ok"`
				GovernedRoles *[]string      `json:"governed_roles"`
				Leases        []string       `json:"leases"`
				VisitLeases   []string       `json:"visit_leases"`
				State         jsontext.Value `json:"state"`
			} `json:"expected"`
		} `json:"cases"`
	} `json:"verifier"`
}

func load(t *testing.T, name string, v any) {
	t.Helper()
	b, err := os.ReadFile("testdata/" + name)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(b, v); err != nil {
		t.Fatal(err)
	}
}

func TestReferenceVerifierVerdicts(t *testing.T) {
	var set conformance
	load(t, "edge.json", &set)
	if set.Format != "kc-conformance-v1" || len(set.Verifier.Cases) == 0 {
		t.Fatalf("unexpected conformance set %q with %d verifier cases", set.Format, len(set.Verifier.Cases))
	}
	for _, c := range set.Verifier.Cases {
		t.Run(c.Name, func(t *testing.T) {
			now, err := ParseTime(c.Now)
			if err != nil {
				t.Fatal(err)
			}
			var applied *Applied
			sv, err := Parse(c.Sealed)
			if err == nil {
				var sealed Sealed
				if sealed, err = SealedFrom(sv); err == nil {
					applied, err = VerifyBundle(sealed, c.Pins, c.State, now, nil)
				}
			}
			if (err == nil) != c.Expected.OK {
				t.Fatalf("ok = %v, want %v (%v)", err == nil, c.Expected.OK, err)
			}
			got := []string{}
			if applied != nil {
				for _, l := range applied.Leases {
					got = append(got, l.LeaseID)
				}
			}
			want := c.Expected.Leases
			if want == nil {
				want = []string{}
			}
			if !equalStrings(got, want) {
				t.Fatalf("live leases %v, want %v", got, want)
			}
			// governed_roles (KeyClerk decision 0025): null when absent or refused, never read as "none governed".
			var governed *[]string
			if applied != nil {
				governed = applied.GovernedRoles
			}
			if (governed == nil) != (c.Expected.GovernedRoles == nil) ||
				(governed != nil && !equalStrings(*governed, *c.Expected.GovernedRoles)) {
				t.Fatalf("governed roles %v, want %v", governed, c.Expected.GovernedRoles)
			}
			if applied == nil || c.Expected.VisitLeases == nil {
				return
			}
			visits := []string{}
			for _, l := range applied.VisitLeases {
				visits = append(visits, l.LeaseID)
			}
			if !equalStrings(visits, c.Expected.VisitLeases) {
				t.Fatalf("live visit leases %v, want %v", visits, c.Expected.VisitLeases)
			}
			// The stored state (floors) as KeyClerk computes it, compared canonically.
			if len(c.Expected.State) > 0 && string(c.Expected.State) != "null" {
				gotState, _ := json.Marshal(applied.State)
				gv, _ := Parse(gotState)
				wv, err := Parse(c.Expected.State)
				if err != nil || !bytes.Equal(Encode(gv), Encode(wv)) {
					t.Fatalf("state %s, want %s", Encode(gv), c.Expected.State)
				}
			}
		})
	}
}

func TestCanonicalMatchesKeyClerk(t *testing.T) {
	var set struct {
		Source string `json:"source"`
		Cases  []struct {
			Input     string  `json:"input"`
			Canonical *string `json:"canonical"`
		} `json:"cases"`
	}
	load(t, "canon.json", &set)
	if set.Source != "keyclerk.edge.canonical" || len(set.Cases) == 0 {
		t.Fatal("canon.json must be generated from keyclerk.edge.canonical")
	}
	for i, c := range set.Cases {
		in, _ := base64.StdEncoding.DecodeString(c.Input)
		v, perr := Parse(in)
		_, cerr := CheckCanonical(in)
		if c.Canonical == nil {
			if perr == nil {
				t.Errorf("case %d %q: KeyClerk cannot encode it, so it must be refused", i, in)
			}
			continue
		}
		want, _ := base64.StdEncoding.DecodeString(*c.Canonical)
		if perr == nil && !bytes.Equal(Encode(v), want) {
			t.Errorf("case %d %q:\n got %q\nwant %q", i, in, Encode(v), want)
		}
		// Signed bytes are accepted exactly when they are KeyClerk's canonical bytes.
		if (cerr == nil) != bytes.Equal(in, want) {
			t.Errorf("case %d %q: canonical check %v, but the input equals KeyClerk's bytes: %v", i, in, cerr, bytes.Equal(in, want))
		}
		// KeyClerk's own output always passes.
		if _, err := CheckCanonical(want); err != nil {
			t.Errorf("case %d: KeyClerk's canonical bytes %q refused: %v", i, want, err)
		}
	}
}

func TestFloorDivFollowsPython(t *testing.T) {
	for _, c := range [][3]int64{{7, 2, 3}, {-7, 2, -4}, {7, -2, -4}, {-7, -2, 3}, {-3600, 3600, -1}, {-1, 3600, -1}, {0, 3600, 0}} {
		if got := floorDiv(c[0], c[1]); got != c[2] {
			t.Errorf("floorDiv(%d, %d) = %d, want %d", c[0], c[1], got, c[2])
		}
	}
}

func TestParseTimeRefusesLooseForms(t *testing.T) {
	for _, s := range []string{"2026-1-5T1:2:3Z", "2026-10-23T10:00:00+00:00", "2026-10-23 10:00:00Z", "2026-10-23T10:00:00.5Z", ""} {
		if _, err := ParseTime(s); err == nil {
			t.Errorf("%q accepted", s)
		}
	}
}

func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

// FuzzCanonical: parsing never panics; whatever parses re-encodes to bytes that are
// canonical and stable; accepted signed bytes are exactly their own encoding.
func FuzzCanonical(f *testing.F) {
	var set struct {
		Cases []struct {
			Input string `json:"input"`
		} `json:"cases"`
	}
	if b, err := os.ReadFile("testdata/canon.json"); err == nil && json.Unmarshal(b, &set) == nil {
		for _, c := range set.Cases {
			in, _ := base64.StdEncoding.DecodeString(c.Input)
			f.Add(in)
		}
	}
	f.Fuzz(func(t *testing.T, in []byte) {
		v, err := Parse(in)
		if err != nil {
			return
		}
		enc := Encode(v)
		v2, err := CheckCanonical(enc)
		if err != nil {
			t.Fatalf("own encoding %q refused: %v", enc, err)
		}
		if !bytes.Equal(Encode(v2), enc) {
			t.Fatalf("encoding not stable for %q", enc)
		}
		if _, err := CheckCanonical(in); (err == nil) != bytes.Equal(in, enc) {
			t.Fatalf("canonical check disagrees with the encoding for %q", in)
		}
	})
}

// FuzzVerifyBundle: arbitrary envelopes never panic and never verify without the key.
func FuzzVerifyBundle(f *testing.F) {
	var set conformance
	if b, err := os.ReadFile("testdata/edge.json"); err == nil && json.Unmarshal(b, &set) == nil {
		for _, c := range set.Verifier.Cases {
			if v, err := Parse(c.Sealed); err == nil {
				if sealed, err := SealedFrom(v); err == nil {
					f.Add(sealed.Bytes, sealed.Signature)
				}
			}
		}
	}
	pins := Pins{Edge: "edge-a", BundleKey: "8a88e3dd7409f195fd52db2d3cba5d72ca6709bf1d94121bf3748801b40f6f5c",
		OfficerKey: "8139770ea87d175f56a35466c34c7ecccb8d8a91b4ee37a25df60f5b8fc9b394"}
	now, _ := ParseTime("2026-10-23T13:00:00Z")
	f.Fuzz(func(t *testing.T, b64, sig string) {
		_, _ = VerifyBundle(Sealed{Bytes: b64, Signature: sig, Key: pins.BundleKey, KeyID: KeyID(pins.BundleKey)},
			pins, State{}, now, nil)
	})
}

// TestCeilingPolicyMatchesKeyClerk runs KeyClerk's ceiling policy vectors (the
// keyclerk/ceiling/decision entrypoint in testdata/edge.json) against the Go port.
func TestCeilingPolicyMatchesKeyClerk(t *testing.T) {
	var set struct {
		Cases []struct {
			Name       string         `json:"name"`
			Entrypoint string         `json:"entrypoint"`
			Input      jsontext.Value `json:"input"`
			Expected   struct {
				Allow    bool     `json:"allow"`
				Refusals []string `json:"refusals"`
			} `json:"expected"`
		} `json:"cases"`
	}
	load(t, "edge.json", &set)
	n := 0
	for _, c := range set.Cases {
		if c.Entrypoint != "keyclerk/ceiling/decision" {
			continue
		}
		n++
		v, err := Parse(c.Input)
		if err != nil {
			t.Fatal(err)
		}
		in := v.(Object)
		var e CeilingEntry
		if err := json.Unmarshal(Encode(in["entry"]), &e); err != nil {
			t.Fatal(err)
		}
		allow, refusals := CeilingDecision(in["ceiling"].(Object), e)
		want := append([]string{}, c.Expected.Refusals...)
		slices.Sort(want) // the vectors hold sets ("sets as sorted lists")
		if allow != c.Expected.Allow || !equalStrings(refusals, want) {
			t.Errorf("%s: allow %v %v, want %v %v", c.Name, allow, refusals, c.Expected.Allow, want)
		}
	}
	if n < 5 {
		t.Fatalf("only %d ceiling cases in the conformance set", n)
	}
}

// The conformance families beside the bundle verifier (keyclerk/edge_conformance.py):
// every case must reach KeyClerk's verdict.
type families struct {
	Statements struct {
		Cases []struct {
			Name     string         `json:"name"`
			Sealed   jsontext.Value `json:"sealed"`
			Required []string       `json:"required"`
			Format   string         `json:"format"`
			Expected struct {
				OK   bool           `json:"ok"`
				Says jsontext.Value `json:"says"`
			} `json:"expected"`
		} `json:"cases"`
	} `json:"statements"`
	Ceilings struct {
		Cases []struct {
			Name       string         `json:"name"`
			Edge       string         `json:"edge"`
			OfficerKey string         `json:"officer_key"`
			Sealed     jsontext.Value `json:"sealed"`
			Floor      int64          `json:"floor"`
			Expected   struct {
				OK bool `json:"ok"`
			} `json:"expected"`
		} `json:"cases"`
	} `json:"ceilings"`
	Ended struct {
		Cases []struct {
			Name         string         `json:"name"`
			Sealed       jsontext.Value `json:"sealed"`
			Pins         Pins           `json:"pins"`
			EnrolmentKey string         `json:"enrolment_key"`
			Expected     struct {
				OK bool `json:"ok"`
			} `json:"expected"`
		} `json:"cases"`
	} `json:"ended"`
	// Email: edge protocol 1.3; absent before KeyClerk 0.26.0, so an older set simply has no cases.
	Email struct {
		Cases []struct {
			Name     string         `json:"name"`
			Sealed   jsontext.Value `json:"sealed"`
			Pins     Pins           `json:"pins"`
			LeaseID  string         `json:"lease_id"`
			Nonce    string         `json:"nonce"`
			Expected struct {
				OK          bool    `json:"ok"`
				EmailSHA256 *string `json:"email_sha256"`
			} `json:"expected"`
		} `json:"cases"`
	} `json:"email"`
	Unlock struct {
		Cases []struct {
			Name        string `json:"name"`
			DeskPrivate string `json:"desk_private"`
			DeskPublic  string `json:"desk_public"`
			EdgePrivate string `json:"edge_private"`
			EdgePublic  string `json:"edge_public"`
			Edge        string `json:"edge"`
			Node        string `json:"node"`
			Person      string `json:"person"`
			Fingerprint string `json:"fingerprint"`
			Target      string `json:"target"`
			Nonce       string `json:"nonce"`
			Minutes     int    `json:"minutes"`
			Expected    struct {
				Code *string `json:"code"`
			} `json:"expected"`
		} `json:"cases"`
	} `json:"unlock"`
	ModuleBytes struct {
		Cases []struct {
			Name     string `json:"name"`
			Wasm     string `json:"wasm"`
			SHA256   string `json:"sha256"`
			Expected struct {
				OK bool `json:"ok"`
			} `json:"expected"`
		} `json:"cases"`
	} `json:"module_bytes"`
}

func TestConformanceFamilies(t *testing.T) {
	var set families
	load(t, "edge.json", &set)
	n := 0
	for _, c := range set.Statements.Cases {
		n++
		v, err := Parse(c.Sealed)
		var says Object
		if err == nil {
			says, err = UnsealMulti(v, c.Required, c.Format)
		}
		if (err == nil) != c.Expected.OK {
			t.Errorf("statements %q: ok = %v, want %v (%v)", c.Name, err == nil, c.Expected.OK, err)
			continue
		}
		if c.Expected.OK {
			want, perr := Parse(c.Expected.Says)
			if perr != nil || !bytes.Equal(Encode(says), Encode(want)) {
				t.Errorf("statements %q: says %s, want %s", c.Name, Encode(says), c.Expected.Says)
			}
		}
	}
	for _, c := range set.Ceilings.Cases {
		n++
		v, err := Parse(c.Sealed)
		var errs []string
		if err != nil {
			errs = []string{err.Error()}
		} else {
			errs, _ = CheckCeiling(c.Edge, c.OfficerKey, v, c.Floor)
		}
		if (len(errs) == 0) != c.Expected.OK {
			t.Errorf("ceilings %q: ok = %v, want %v (%v)", c.Name, len(errs) == 0, c.Expected.OK, errs)
		}
	}
	for _, c := range set.Ended.Cases {
		n++
		v, err := Parse(c.Sealed)
		if err == nil {
			var sealed Sealed
			if sealed, err = SealedFrom(v); err == nil {
				_, err = VerifyEnded(sealed, c.Pins, c.EnrolmentKey)
			}
		}
		if (err == nil) != c.Expected.OK {
			t.Errorf("ended %q: ok = %v, want %v (%v)", c.Name, err == nil, c.Expected.OK, err)
		}
	}
	for _, c := range set.Email.Cases {
		n++
		email, has, err := "", false, error(nil)
		v, err := Parse(c.Sealed)
		if err == nil {
			var sealed Sealed
			if sealed, err = SealedFrom(v); err == nil {
				email, has, err = VerifyEmail(sealed, c.Pins, c.LeaseID, c.Nonce)
			}
		}
		if (err == nil) != c.Expected.OK {
			t.Errorf("email %q: ok = %v, want %v (%v)", c.Name, err == nil, c.Expected.OK, err)
			continue
		}
		var got *string // the address by digest: no address sits in a published file
		if err == nil && has {
			sum := sha256.Sum256([]byte(email))
			h := hex.EncodeToString(sum[:])
			got = &h
		}
		if (got == nil) != (c.Expected.EmailSHA256 == nil) || (got != nil && *got != *c.Expected.EmailSHA256) {
			t.Errorf("email %q: address digest %v, want %v", c.Name, got, c.Expected.EmailSHA256)
		}
	}
	for _, c := range set.Unlock.Cases {
		n++
		var codes []*string
		for _, own := range []string{c.EdgePrivate, c.DeskPrivate} {
			var code *string
			if k, err := UnlockPrivate(own); err == nil {
				if secret, err := UnlockSecret(k, c.DeskPublic, c.EdgePublic, c.Edge, c.Node); err == nil {
					if s, err := UnlockCode(secret, c.Edge, c.Node, c.Person, c.Fingerprint, c.Target, c.Nonce, c.Minutes); err == nil {
						code = &s
					}
				}
			}
			codes = append(codes, code)
		}
		same := (codes[0] == nil && codes[1] == nil) || (codes[0] != nil && codes[1] != nil && *codes[0] == *codes[1])
		want := c.Expected.Code
		if !same || (want == nil) != (codes[0] == nil) || (want != nil && *want != *codes[0]) {
			t.Errorf("unlock %q: node %v desk %v, want %v", c.Name, deref(codes[0]), deref(codes[1]), deref(want))
		}
	}
	for _, c := range set.ModuleBytes.Cases {
		n++
		raw, err := base64.StdEncoding.DecodeString(c.Wasm)
		ok := err == nil && len(VerifyModule(raw, c.SHA256)) == 0
		if ok != c.Expected.OK {
			t.Errorf("module_bytes %q: ok = %v, want %v", c.Name, ok, c.Expected.OK)
		}
	}
	if n < 30 {
		t.Fatalf("only %d family cases in the conformance set", n)
	}
}

func deref(s *string) string {
	if s == nil {
		return "<refused>"
	}
	return *s
}
